// ============================================================================
// Task 112 — Model & Strategy Performance Report API (read-only).
// Serves the machine-readable report generated by scripts/task112_build_report.py
// from committed repository evidence (Tasks 79-111). Missing values in the
// source artifacts are marked "Not available in source evidence" there.
// ============================================================================
import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";
import { guardUser } from "@/lib/latent/access-control";

export const dynamic = "force-dynamic";

const REP = path.join(process.cwd(), "data", "reports", "model_strategy_performance_latest.json");

export async function GET(req: Request) {
  const __g = await guardUser(req, "tab.model_report");
  if (__g) return __g;
  try {
    const report = JSON.parse(await fs.readFile(REP, "utf8"));
    return NextResponse.json({ ...report, notice: "SHADOW / RESEARCH ONLY — NOT AN ORDER" });
  } catch {
    return NextResponse.json(
      { error: "report_not_generated", hint: "run scripts/task112_build_report.py" },
      { status: 404 }
    );
  }
}
